/** Render an inline SVG icon by glyph name; unknown names fall back to `category`. */
export function Ic({ n, size = 16, style, className }: { n: string; size?: number; style?: CSSProperties; className?: string }) {
  return (
    <svg
      className={className}
      width={size} height={size} viewBox="0 0 24 24" fill="none"
      stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round"
      style={{ display: "inline-block", verticalAlign: "middle", flex: "0 0 auto", ...style }}
      dangerouslySetInnerHTML={{ __html: ICONS[n] ?? ICONS.category }}
    />
  );
}
